import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { templateApi } from '../services/api';

// Turn a template's "Navy & White" style colorScheme string into two hex-ish
// swatches, purely for a live visual preview — no design assets needed.
function swatchColors(colorScheme) {
  const map = {
    navy: '#1f2f4d', white: '#ffffff', slate: '#475569', teal: '#0d9488',
    coral: '#ff7f66', charcoal: '#2b2b2b', black: '#111111', gold: '#c9a227',
    blue: '#2563eb', purple: '#7c3aed',
  };
  const words = (colorScheme || '').toLowerCase().split(/[^a-z]+/).filter(Boolean);
  const [a, b] = words.map((w) => map[w] || '#cfd4e0');
  return [a || '#4f7cff', b || '#eef1f5'];
}

export default function TemplateLibrary() {
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    templateApi.getAll()
      .then((res) => setTemplates(res.data))
      .finally(() => setLoading(false));
  }, []);

  return (
    <div className="page-container">
      <h1>Template Library</h1>
      <p className="muted">Industry-categorized templates. Premium templates require a Premium subscription. Pick one to start a resume styled with it.</p>
      {loading && <p>Loading templates…</p>}
      <div className="template-grid">
        {templates.map((t) => {
          const [primary, secondary] = swatchColors(t.colorScheme);
          return (
            <div className="template-card" key={t.id}>
              <div
                className="template-thumb"
                style={{ background: `linear-gradient(135deg, ${primary} 55%, ${secondary} 55%)`, fontFamily: t.fontFamily }}
              />
              <h3 style={{ fontFamily: t.fontFamily }}>{t.name}</h3>
              <p className="muted">{t.industryCategory} · {t.fontFamily} · {t.colorScheme}</p>
              <div className="template-tags">
                {t.premiumOnly && <span className="tag premium">Premium</span>}
                {t.atsFriendly && <span className="tag ats">ATS-friendly</span>}
              </div>
              <div className="card-actions" style={{ marginTop: '10px' }}>
                {t.premiumOnly ? (
                  <button type="button" className="btn-link" disabled title="Upgrade to Premium to use this template">
                    Requires Premium
                  </button>
                ) : (
                  <Link to={`/resume/new?template=${t.id}`} className="btn-link">Use This Template</Link>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
